// Parse incoming WhatsApp webhook payload
const body = $input.first().json.body || $input.first().json;

if (body.object !== 'whatsapp_business_account') {
  return [{ json: { skip: true } }];
}

const message = body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!message) return [{ json: { skip: true } }];

const from = message.from;
const msgType = message.type;
let msgText = '';
let listReplyId = '';

if (msgType === 'text') {
  msgText = (message.text?.body || '').trim();
} else if (msgType === 'interactive') {
  listReplyId = message.interactive?.list_reply?.id || message.interactive?.button_reply?.id || '';
  msgText = listReplyId;
}

const textLower = msgText.toLowerCase();

// Classify intent
const greetings = ['hi', 'hello', 'hey', 'namaste', 'start', 'menu', 'help', 'helo', 'jai'];
const isGreeting = greetings.some(g => textLower.includes(g)) || (textLower.length <= 3 && !/^\d+$/.test(textLower));
const isNumber = /^\d+$/.test(msgText.trim());

return [{ json: {
  from,
  msgText,
  textLower,
  isGreeting,
  isNumber,
  selectedIndex: isNumber ? parseInt(msgText.trim(), 10) - 1 : -1,
  msgType,
  listReplyId
}}];

// Build the WhatsApp welcome message with dynamic services
const servicesData = $input.first().json.data || [];
const from = $('Parse Message').first().json.from;
const shopName = 'Maa Durga Jan Seva Kendra';

const numberEmojis = ['1⃣','2⃣','3⃣','4⃣','5⃣','6⃣','7⃣','8⃣','9⃣','🔟'];
const menuText = servicesData.map((s, i) => `${numberEmojis[i] || (i+1)+'.'} ${s.name}`).join('\n');

const payload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: from,
  type: 'text',
  text: {
    body: `🙏 *Welcome to ${shopName}!*\n\nWe provide CSC & online digital services.\n\nPlease select a service by replying with the number:\n\n${menuText}\n\nReply with the number of the service you need.`
  }
};

return [{ json: { payload, from, services: servicesData } }];

// Get the selected service
const services = $input.first().json.data || [];
const selectedIndex = $('Parse Message').first().json.selectedIndex;
const from = $('Parse Message').first().json.from;

const selected = services[selectedIndex];
if (!selected) {
  return [{ json: { error: true, from, totalServices: services.length } }];
}

return [{ json: { selected, from, selectedIndex } }];

// Build the service info + upload link reply
const sessionData = $input.first().json;
const resolvedData = $('Resolve Selected Service').first().json;
const selected = resolvedData.selected;
const from = resolvedData.from;

const uploadUrl = sessionData.upload_url || $vars.PUBLIC_APP_URL;
const expiryMin = 60;

const docs = (selected.documents || []).filter(d => d.is_required).map(d => `✅ ${d.document_name}`).join('\n');

const replyText = `📄 *${selected.name}*${
  selected.hindi_title ? `\n(${selected.hindi_title})` : ''
}\n\nRequired Documents:\n${docs || 'Contact the shop for details.'}\n\nPlease keep these ready and upload using the link below:\n\n🔗 ${uploadUrl}\n\n_Link valid for ${expiryMin} minutes._\n\n*Type "Hi" to see the Main Menu again.*`;

return [{ json: {
  payload: {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: from,
    type: 'text',
    text: { body: replyText }
  },
  from
}}];
